const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Palm Springs, California
  const palmSprings = ee.Geometry.Point([-116.5466, 33.8303]);
  const bufferGeom = palmSprings.buffer(5000); // 5km buffer

  // Define date ranges
  const jul2017_start = '2017-07-15';
  const jul2017_end = '2017-07-21';

  // Baseline period: July 15-21 for years 2001-2010
  const baselineYears = [2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010];

  // Acquire 2017 LST data
  const col2017 = ee.ImageCollection('MODIS/006/MOD11A2')
    .filterDate(jul2017_start, jul2017_end)
    .filterBounds(bufferGeom);

  const size2017 = col2017.size().getInfo();
  print(`2017 Images: ${size2017}`);

  if (size2017 === 0) {
    print("No LST data for July 2017.");
    print("C1");
    return;
  }

  // Acquire baseline LST data (2001-2010, same calendar dates)
  let baselineCol = ee.ImageCollection([]);
  for (let year of baselineYears) {
    const startDate = `${year}-07-15`;
    const endDate = `${year}-07-21`;
    const yearCol = ee.ImageCollection('MODIS/006/MOD11A2')
      .filterDate(startDate, endDate)
      .filterBounds(bufferGeom);
    baselineCol = baselineCol.merge(yearCol);
  }

  const sizeBaseline = baselineCol.size().getInfo();
  print(`Baseline Images (2001-2010): ${sizeBaseline}`);

  if (sizeBaseline === 0) {
    print("No baseline LST data available.");
    print("C1");
    return;
  }

  // Extract LST band (night LST in Kelvin, divide by 100 to get actual K)
  const lst2017 = col2017.select('LST_Night_1km').median().multiply(0.02).subtract(273.15); // Convert to Celsius
  const lstBaseline = baselineCol.select('LST_Night_1km').median().multiply(0.02).subtract(273.15);

  // Calculate statistics
  const stats2017 = lst2017.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: bufferGeom,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const statsBaseline = lstBaseline.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: bufferGeom,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const val2017 = stats2017['LST_Night_1km'];
  const valBaseline = statsBaseline['LST_Night_1km'];

  print(`2017 LST (Jul 15-21): ${(val2017 !== null ? val2017.toFixed(2) : 'null')}°C`);
  print(`Baseline LST (2001-2010): ${(valBaseline !== null ? valBaseline.toFixed(2) : 'null')}°C`);

  // Validate results
  if (val2017 === null || valBaseline === null) {
    print("LST calculation returned null.");
    print("C3");
    return;
  }

  if (isNaN(val2017) || isNaN(valBaseline)) {
    print("LST values are NaN.");
    print("C3");
    return;
  }

  // Check for physically unreasonable values (desert night temps should be -20 to +30°C)
  if (val2017 < -50 || val2017 > 50 || valBaseline < -50 || valBaseline > 50) {
    print("LST values out of reasonable range.");
    print("C3");
    return;
  }

  // Compare
  const diff = val2017 - valBaseline;
  print(`Difference (2017 - Baseline): ${diff.toFixed(2)}°C`);

  if (val2017 > valBaseline) {
    print("A");
  } else {
    print("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
